using System.Security.Cryptography;
using System.Text.Json;
using UnscRelay.Core;
internal static class LocalAccountStartupChecks
{
 public static async Task<int> Run(){var root=Directory.CreateTempSubdirectory("relay-startup-erasure-");var count=0;void Check(bool value,string label){if(!value)throw new Exception(label);count++;Console.WriteLine("PASS local account startup: "+label);}try{using var key=ECDsa.Create(ECCurve.NamedCurves.nistP256);var pub=key.ExportSubjectPublicKeyInfo();var kid=Convert.ToHexString(SHA256.HashData(pub))[..32];var verifier=new ErasureReceiptVerifier(new Dictionary<string,string>{{kid,Convert.ToBase64String(pub)}});var now=DateTimeOffset.UtcNow;var a=new AccountSyncState{Owner=new string('A',64),Subject="61616161-6161-4161-8161-616161616161",Activated=true};new AccountSyncStore(root.FullName).Save(a);var spaces=new AccountWorkspaces(root.FullName);spaces.Remember(a);var claims=new ErasureReceiptClaims(1,"https://unsc.responda.eu","unsc-relay-desktop-erasure",a.Owner,a.Subject,Guid.NewGuid(),now.AddDays(-31).ToUnixTimeMilliseconds(),now.AddDays(-1).ToUnixTimeMilliseconds(),"completed",now.ToUnixTimeMilliseconds());string Encode(byte[] value)=>Convert.ToBase64String(value).TrimEnd('=').Replace('+','-').Replace('/','_');var payload=JsonSerializer.SerializeToUtf8Bytes(claims,VaultSyncCrypto.Json);var receipt=new ErasureReceipt(kid,Encode(payload),Encode(key.SignData(payload,HashAlgorithmName.SHA256,DSASignatureFormat.IeeeP1363FixedFieldConcatenation)));var journal=new LocalErasureJournal(root.FullName,verifier);journal.Accept(receipt,a.Owner,a.Subject,claims.RequestId,Guid.Empty);File.Delete(Path.Combine(root.FullName,"account-sync.dpapi"));File.WriteAllText(Path.Combine(root.FullName,"profiles.json"),"unattributed A residual");var b=spaces.Add("b@example.invalid");spaces.Select(b);var bPath=spaces.DirectoryFor(b);var state=new AccountSyncState{Owner=new string('B',64),Activated=false};new AccountSyncStore(bPath).Save(state);var startup=new LocalAccountStartup(root.FullName,journal);try{await startup.Resume(b,_=>Task.CompletedTask);throw new Exception("Unbound B opened after A cleanup failure");}catch(IOException){Check(!journal.Notices().Single().Completed,"startup remains closed when selected B has no subject and A cannot be cleaned");}state.Subject="62626262-6262-4262-8262-626262626262";new AccountSyncStore(bPath).Save(state);File.WriteAllText(Path.Combine(bPath,"keys.vault"),"B vault must not be read before authentication");using(var lockedVault=new FileStream(Path.Combine(bPath,"keys.vault"),FileMode.Open,FileAccess.Read,FileShare.None)){await startup.Resume(b,_=>Task.CompletedTask);Check(File.ReadAllText(Path.Combine(root.FullName,"profiles.json"))=="unattributed A residual"&&!journal.Notices().Single().Completed,"bound disconnected B may start without reading its vault or removing ambiguous A data");}var proof=Path.Combine(root.FullName,"ErasureJournal",a.Owner+".dpapi");var bytes=File.ReadAllBytes(proof);bytes[bytes.Length/2]^=1;File.WriteAllBytes(proof,bytes);try{await startup.Resume(b,_=>Task.CompletedTask);throw new Exception("Corrupt global journal bypassed");}catch(Exception error)when(error is IOException or CryptographicException or InvalidOperationException){Check(true,"global receipt corruption blocks startup even for independently bound B");}Console.WriteLine("Local account startup checks: "+count);return 0;}finally{root.Delete(true);}}
}
